curr_flow = json.load(open('BillingDisputeResolution.flow'))
ds_def = next(d for d in curr_flow['definitions'] if d.get('nodeType') == 'uipath.connector.uipath-uipath-dataservice.query-entity-records')

ANALYST_AGENT_ID = 'b2986a34-89fc-406b-b6fc-fec1415a3b2c'
