IXP_NODE_TYPE = 'uipath.ixp.invoices-billing-f0c606f9-ixp.99f5bbfa-5f29-8033-8662-25001b6bb18e-79a7d12e-da84-4bf4-ab60-7f34b44dd178'
APIWF_NODE_TYPE = 'uipath.core.api-workflow.07d45a91-9413-4dad-82ff-28306c2d85ea'
CTX_NODE_TYPE = 'uipath.agent.resource.context.index.billing-dispute-sop-index.cc45b9b4-dbf6-47b3-40ac-08debc0cec5b'

ixp_inp = ixp_def['inputDefaults']
