        "description": "Credit amount from analyst agent"
      },
      {
        "id": "rationale",
        "direction": "out",
        "type": "string",
        "description": "Rationale from analyst agent"
      },
      {
        "id": "resolutionEmailBody",
        "direction": "out",
        "type": "string",
        "description": "Resolution email body"
      }
    ],
    "nodes": [
      {"id": "start.output", "type": "object", "description": "Data passed when manually triggering the workflow.", "binding": {"nodeId": "start", "outputId": "output"}},
      {"id": "extractInvoice.output", "type": "object", "description": "IxP extraction output", "binding": {"nodeId": "extractInvoice", "outputId": "output"}},
      {"id": "extractInvoice.error", "type": "object", "description": "IxP extraction error", "binding": {"nodeId": "extractInvoice", "outputId": "error"}},
      {"id": "normalizeData.output", "type": "object", "description": "Normalized invoice fields", "binding": {"nodeId": "normalizeData", "outputId": "output"}},
      {"id": "normalizeData.error", "type": "object", "description": "Error from normalize script", "binding": {"nodeId": "normalizeData", "outputId": "error"}},
      {"id": "crmLookup1.output", "type": "object", "description": "CRM lookup result", "binding": {"nodeId": "crmLookup1", "outputId": "output"}},
      {"id": "crmLookup1.error", "type": "object", "description": "CRM lookup error", "binding": {"nodeId": "crmLookup1", "outputId": "error"},
       "schema": {"$schema": "http://json-schema.org/draft-07/schema#", "type": "object", "required": ["code","message","detail","category","status"], "properties": {"code": {"type": "string"}, "message": {"type": "string"}, "detail": {"type": "string"}, "category": {"type": "string"}, "status": {"type": "integer"}}, "additionalProperties": False}},
      {"id": "erpLookup1.output", "type": "object", "description": "ERP lookup result", "binding": {"nodeId": "erpLookup1", "outputId": "output"}},
      {"id": "erpLookup1.error", "type": "object", "description": "ERP lookup error", "binding": {"nodeId": "erpLookup1", "outputId": "error"},
       "schema": {"$schema": "http://json-schema.org/draft-07/schema#", "type": "object", "required": ["code","message","detail","category","status"], "properties": {"code": {"type": "string"}, "message": {"type": "string"}, "detail": {"type": "string"}, "category": {"type": "string"}, "status": {"type": "integer"}}, "additionalProperties": False}},
      {"id": "mergeResults.output", "type": "object", "description": "Merged CRM+ERP outputs", "binding": {"nodeId": "mergeResults", "outputId": "output"}},
      {"id": "detectDiscrepancies.output", "type": "object", "description": "Discrepancy detection output", "binding": {"nodeId": "detectDiscrepancies", "outputId": "output"}},
      {"id": "detectDiscrepancies.error", "type": "object", "description": "Discrepancy detection error", "binding": {"nodeId": "detectDiscrepancies", "outputId": "error"}},
      {"id": "disputeAnalyst.output", "type": "object", "description": "Analyst agent output", "binding": {"nodeId": "disputeAnalyst", "outputId": "output"}},
      {"id": "disputeAnalyst.error", "type": "object", "description": "Analyst agent error", "binding": {"nodeId": "disputeAnalyst", "outputId": "error"}},
      {"id": "logCreditAmount.output", "type": "object", "description": "Credit amount log output", "binding": {"nodeId": "logCreditAmount", "outputId": "output"}},
      {"id": "logCreditAmount.error", "type": "object", "description": "Credit amount log error", "binding": {"nodeId": "logCreditAmount", "outputId": "error"}},
      {"id": "financialPosting.output", "type": "object", "description": "Financial posting output", "binding": {"nodeId": "financialPosting", "outputId": "output"}},
      {"id": "financialPosting.error", "type": "object", "description": "Financial posting error", "binding": {"nodeId": "financialPosting", "outputId": "error"}},
      {"id": "resolutionWriter.output", "type": "object", "description": "Resolution writer agent output", "binding": {"nodeId": "resolutionWriter", "outputId": "output"}},
      {"id": "resolutionWriter.error", "type": "object", "description": "Resolution writer error", "binding": {"nodeId": "resolutionWriter", "outputId": "error"}}
    ],
    "variableUpdates": {}
  },
  "nodes": [
    # 1. Manual trigger
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {"label": "Manual trigger"},
      "inputs": {
        "entryPointId": "b2d3a44d-249d-45ab-8cc7-ffe7308e42a5",
        "isDefaultEntryPoint": True
      }
    },
    # 2. IxP Invoice Extraction
    {
      "id": "extractInvoice",
      "type": IXP_NODE_TYPE,
      "typeVersion": "1.0.0",
      "display": {"label": "Invoice Extraction (IxP)"},
      "inputs": {
        "model": {
          "id": ixp_model_blob.get("id"),
          "modelName": model_name,
          "modelDisplayName": ixp_model_blob.get("modelDisplayName"),
          "folderKey": ixp_model_blob.get("folderKey"),
          "folderName": ixp_model_blob.get("folderName"),
          "folderPath": ixp_model_blob.get("folderPath"),
          "description": ""
        },
        "modelName": ixp_inp.get("modelName"),
        "projectName": ixp_inp.get("projectName"),
        "folderKey": ixp_inp.get("folderKey"),
        "folderName": ixp_inp.get("folderName"),
        "fileRef": "=js:$vars.start.output.disputedInvoice",
        "versionTag": "",
        "pageRange": ""
      },
      "outputs": {
        "output": ixp_out_def.get("output"),
        "error": ixp_out_def.get("error")
      }
    },
    # 3. Normalize Data script
    {
      "id": "normalizeData",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Normalize Data"},
      "inputs": {
        "script": "const fields = ($vars.extractInvoice.output.ExtractionResult && $vars.extractInvoice.output.ExtractionResult.ResultsDocument && $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields) || [];\nconst normalized = fields.map(function(f) {\n  return { Id: f.FieldId, Name: f.FieldName, Value: (f.Values && f.Values[0]) || null, Type: f.FieldType, IsMissing: f.IsMissing };\n});\nconst rawInvoiceNumber = $vars.start.output.webhookPayload && $vars.start.output.webhookPayload.invoice && $vars.start.output.webhookPayload.invoice.invoiceNumber ? $vars.start.output.webhookPayload.invoice.invoiceNumber : '';\nconst trimmed = rawInvoiceNumber.trim().toUpperCase();\nconst normalizedInvoiceNumber = trimmed.startsWith('MCS-') ? trimmed : 'MCS-' + trimmed;\nreturn { fields: normalized, normalizedInvoiceNumber: normalizedInvoiceNumber };"
      },
      "outputs": {
        "output": {"type": "object", "description": "Normalized invoice data", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Script error", "source": "=result.Error", "var": "error"}
      }
    },
    # 4. CRM Lookup - connector node (already added via node add, id crmLookup1)
    {
      "id": "crmLookup1",
      "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
      "typeVersion": "1.0.0",
      "display": {"label": "CRM Lookup"},
      "inputs": {}
    },
    # 5. ERP Lookup - connector node (already added via node add, id erpLookup1)
    {
      "id": "erpLookup1",
      "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
      "typeVersion": "1.0.0",
      "display": {"label": "ERP Lookup"},
      "inputs": {}
    },
    # 6. Merge node
    {
      "id": "mergeResults",
      "type": "core.logic.merge",
      "typeVersion": "1.0",
      "display": {"label": "Merge"},
      "inputs": {}
    },
    # 7. Discrepancy Detection script
    {
      "id": "detectDiscrepancies",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Discrepancy Detection"},
      "inputs": {
        "script": "var disputedItems = ($vars.start.output.webhookPayload && $vars.start.output.webhookPayload.dispute && $vars.start.output.webhookPayload.dispute.disputedLineItems) || [];\nvar erpRows = ($vars.erpLookup1.output && $vars.erpLookup1.output.value) || [];\nvar mismatches = [];\nvar totalOvercharge = 0;\nvar totalUndercharge = 0;\ndisputedItems.forEach(function(item) {\n  var erp = null;\n  for (var i = 0; i < erpRows.length; i++) {\n    if (erpRows[i].lineNumber === item.lineNumber || String(erpRows[i].LineNumber) === String(item.lineNumber)) {\n      erp = erpRows[i];\n      break;\n    }\n  }\n  if (erp) {\n    var contractPrice = erp.unitPrice || erp.UnitPrice || 0;\n    var billedPrice = item.unitPrice || 0;\n    var diff = billedPrice - contractPrice;\n    if (diff !== 0) {\n      var mismatch = { lineNumber: item.lineNumber, billedUnitPrice: billedPrice, contractUnitPrice: contractPrice, quantity: item.quantity, priceDiff: diff, overcharged: diff > 0, description: item.description };\n      mismatches.push(mismatch);\n      if (diff > 0) { totalOvercharge += diff * (item.quantity || 1); }\n      else { totalUndercharge += Math.abs(diff) * (item.quantity || 1); }\n    }\n  }\n});\nreturn { mismatches: mismatches, totalOvercharge: totalOvercharge, totalUndercharge: totalUndercharge, mismatchCount: mismatches.length };"
      },
      "outputs": {
        "output": {"type": "object", "description": "Discrepancy analysis results", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Script error", "source": "=result.Error", "var": "error"}
      }
    },
    # 8. Dispute Analyst Agent (inline)
    {
      "id": "disputeAnalyst",
      "type": "uipath.agent.autonomous",
      "typeVersion": "1.2",
      "display": {"label": "Dispute Analyst Agent"},
      "inputs": {
        "systemPrompt": "You are a billing dispute analyst. Analyze the invoice, CRM account data, ERP contract data, and discrepancy summary to produce a determination and recommended action.",
        "userPrompt": "Analyze the billing dispute and return a structured determination.",
        "source": ANALYST_AGENT_ID,
        "agentInputVariables": [
          {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload"},
          {"id": "normalizeData__output__fields", "type": "object", "binding": "=$vars.normalizeData.output.fields"},
          {"id": "normalizeData__output__normalizedInvoiceNumber", "type": "string", "binding": "=$vars.normalizeData.output.normalizedInvoiceNumber"},
          {"id": "crmLookup1__output__value", "type": "object", "binding": "=$vars.crmLookup1.output.value"},
          {"id": "erpLookup1__output__value", "type": "object", "binding": "=$vars.erpLookup1.output.value"},
          {"id": "detectDiscrepancies__output__mismatches", "type": "object", "binding": "=$vars.detectDiscrepancies.output.mismatches"},
          {"id": "detectDiscrepancies__output__totalOvercharge", "type": "number", "binding": "=$vars.detectDiscrepancies.output.totalOvercharge"},
          {"id": "detectDiscrepancies__output__totalUndercharge", "type": "number", "binding": "=$vars.detectDiscrepancies.output.totalUndercharge"}
        ],
        "agentOutputVariables": [
          {"id": "determination", "type": "string"},
          {"id": "recommendedAction", "type": "string"},
          {"id": "autoResolutionEligible", "type": "boolean"},
          {"id": "creditAmount", "type": "number"},
          {"id": "confidence", "type": "number"},
          {"id": "rationale", "type": "string"}
        ]
      },
      "outputs": {
        "output": {"type": "object", "description": "Agent response", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
      }
    },
    # 9. Context node for Billing Dispute SOP Index (attached to disputeAnalyst)
    {
      "id": "billingDisputeCtx",
      "type": CTX_NODE_TYPE,
      "typeVersion": "1.0.0",
      "display": {"label": "Billing Dispute SOP Index"},
      "inputs": {"source": CTX_RES_UUID}
    },
    # 10. Switch on recommendedAction
    {
      "id": "routeAction",
      "type": "core.logic.switch",
      "typeVersion": "1.1",
      "display": {"label": "Route by Recommended Action"},
      "inputs": {
        "cases": [
          {"id": "escalate", "label": "Escalate to Manager", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'escalate_to_manager'"},
          {"id": "autoResolve", "label": "Auto Resolve", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'auto_resolve'"},
          {"id": "reject", "label": "Reject", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'reject'"}
        ]
      }
    },
    # 11. Approval Decision (manager approval - evaluates false=Approved by default)
    {
      "id": "managerApproval",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {"label": "Manager Approval"},
      "inputs": {
        "expression": "false",
        "trueLabel": "Rejected",
        "falseLabel": "Approved"
      }
    },
    # 12. Log Credit Amount script (auto_resolve branch)
    {
      "id": "logCreditAmount",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Log Credit Amount"},
      "inputs": {
        "script": "var credit = $vars.disputeAnalyst.output.creditAmount;\nreturn { creditAmount: credit };"
      },
      "outputs": {
        "output": {"type": "object", "description": "Credit amount", "source": "=result.response", "var": "output"},
        "error": {"type": "object", "description": "Script error", "source": "=result.Error", "var": "error"}
      }
    },
